import enum, uuid
from datetime import datetime
from typing import Any, Optional
from sqlalchemy import Boolean, DateTime, Enum, ForeignKey, Integer, LargeBinary, Numeric, String, Text, UniqueConstraint, JSON, func
from sqlalchemy.dialects.postgresql import UUID, ARRAY
from sqlalchemy.orm import Mapped, mapped_column
from ..db import Base
class Role(str,enum.Enum): recruiter="recruiter"; client="client"; delivery_head="delivery_head"
class Client(Base):
    __tablename__="clients"; id:Mapped[uuid.UUID]=mapped_column(UUID(as_uuid=True),primary_key=True,default=uuid.uuid4); created_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now()); updated_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now(),onupdate=func.now()); name:Mapped[str]=mapped_column(String(200)); industry:Mapped[str]=mapped_column(String(120))
class User(Base):
    __tablename__="users"; id:Mapped[uuid.UUID]=mapped_column(UUID(as_uuid=True),primary_key=True,default=uuid.uuid4); created_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now()); updated_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now(),onupdate=func.now()); email:Mapped[str]=mapped_column(String(320),unique=True,index=True); password_hash:Mapped[str]=mapped_column(String(255)); full_name:Mapped[str]=mapped_column(String(200)); role:Mapped[Role]=mapped_column(Enum(Role)); client_id:Mapped[Optional[uuid.UUID]]=mapped_column(ForeignKey("clients.id"),nullable=True)
class Requisition(Base):
    __tablename__="requisitions"; id:Mapped[uuid.UUID]=mapped_column(UUID(as_uuid=True),primary_key=True,default=uuid.uuid4); created_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now()); updated_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now(),onupdate=func.now()); client_id:Mapped[uuid.UUID]=mapped_column(ForeignKey("clients.id")); owner_id:Mapped[uuid.UUID]=mapped_column(ForeignKey("users.id")); title:Mapped[str]=mapped_column(String(200)); location:Mapped[str]=mapped_column(String(120)); jd_text:Mapped[str]=mapped_column(Text); status:Mapped[str]=mapped_column(String(20),default="open"); openings:Mapped[int]=mapped_column(Integer,default=1)
class Scorecard(Base):
    __tablename__="scorecards"; __table_args__=(UniqueConstraint("requisition_id","version"),); id:Mapped[uuid.UUID]=mapped_column(UUID(as_uuid=True),primary_key=True,default=uuid.uuid4); created_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now()); updated_at:Mapped[datetime]=mapped_column(DateTime,server_default=func.now(),onupdate=func.now()); requisition_id:Mapped[uuid.UUID]=mapped_column(ForeignKey("requisitions.id")); version:Mapped[int]=mapped_column(Integer); is_active:Mapped[bool]=mapped_column(Boolean,default=True); created_by:Mapped[uuid.UUID]=mapped_column(ForeignKey("users.id")); criteria:Mapped[list[Any]]=mapped_column(JSON,default=list); ai_draft:Mapped[dict[str,Any]]=mapped_column(JSON,default=dict); ai_confidence:Mapped[dict[str,Any]]=mapped_column(JSON,default=dict)
def simple(name:str,cols:dict[str,Any]):
    attrs={"__tablename__":name,"id":mapped_column(UUID(as_uuid=True),primary_key=True,default=uuid.uuid4),"created_at":mapped_column(DateTime,server_default=func.now()),"updated_at":mapped_column(DateTime,server_default=func.now(),onupdate=func.now())}; attrs.update({k:mapped_column(v) for k,v in cols.items()}); return type(name.title().replace("_",""),(Base,),attrs)
UploadBatch=simple("upload_batches",{"requisition_id":ForeignKey("requisitions.id"),"uploaded_by":ForeignKey("users.id"),"total":Integer,"processed":Integer,"failed":Integer,"duplicates":Integer,"status":String(20)})
CvFile=simple("cv_files",{"batch_id":ForeignKey("upload_batches.id"),"candidate_id":ForeignKey("candidates.id"),"filename":String(255),"mime":String(100),"size_bytes":Integer,"sha256":String(64),"status":String(20),"parse_method":String(20),"error_code":String(80),"error_message":Text,"attempts":Integer})
CvBlob=simple("cv_blobs",{"cv_file_id":ForeignKey("cv_files.id"),"data":LargeBinary})
Candidate=simple("candidates",{"candidate_code":String(30),"full_name":String(200),"email":String(320),"phone":String(40),"current_role":String(200),"total_exp_years":Numeric,"skills":ARRAY(String),"notice_days":Integer,"current_ctc_lpa":Numeric,"expected_ctc_lpa":Numeric,"location":String(120),"education":JSON,"experience":JSON,"raw_text":Text,"redacted_text":Text,"parse_confidence":String(20),"duplicate_of_id":ForeignKey("candidates.id"),"consent_status":String(20),"consent_source":String(100),"consent_at":DateTime,"deleted_at":DateTime})
Application=simple("applications",{"requisition_id":ForeignKey("requisitions.id"),"candidate_id":ForeignKey("candidates.id"),"cv_file_id":ForeignKey("cv_files.id"),"stage":String(30),"recruiter_opened_at":DateTime,"submitted_at":DateTime,"submitted_by":ForeignKey("users.id"),"recruiter_note":Text})
Score=simple("scores",{"application_id":ForeignKey("applications.id"),"scorecard_id":ForeignKey("scorecards.id"),"total":Integer,"coverage":Numeric,"band":String(20),"confidence":String(20),"needs_review":Boolean,"review_reasons":ARRAY(String),"criteria":JSON,"scoring_input":Text,"model":String(100),"prompt_version":String(50),"latency_ms":Integer})
ClientFeedback=simple("client_feedback",{"application_id":ForeignKey("applications.id"),"client_user_id":ForeignKey("users.id"),"action":String(30),"reason_code":String(30),"note":Text,"proposed_slots":JSON}); StageEvent=simple("stage_events",{"application_id":ForeignKey("applications.id"),"from_stage":String(30),"to_stage":String(30),"actor_id":ForeignKey("users.id"),"note":Text}); AccessLog=simple("access_logs",{"user_id":ForeignKey("users.id"),"candidate_id":ForeignKey("candidates.id"),"action":String(30),"ip":String(64),"user_agent":String(500)}); DeletionRequest=simple("deletion_requests",{"candidate_id":ForeignKey("candidates.id"),"requested_by":ForeignKey("users.id"),"status":String(30),"completed_at":DateTime})

